-- Mechanical v6: one shared Card pool. Historic catalog rows remain for foreign-key/replay history.
update public.content_catalog set starter=false;
update public.content_catalog set enabled=false where kind='die';
-- Shared pool v5: only the curated starter collection is granted to new accounts.
-- Shared pool v5: only the curated starter collection is granted to new accounts.
-- Shared pool v5: only the curated starter collection is granted to new accounts.
on conflict(id) do update set definition=excluded.definition,version=excluded.version,starter=excluded.starter,enabled=true;

create temporary table legacy_card_ids(old_id text primary key,new_id text not null) on commit drop;
-- Do not grant the whole new set; preserve only old entitlements plus the starter collection.
update public.content_catalog set enabled=false,starter=false where id in(select old_id from legacy_card_ids);
create or replace function public.meets_affinity(affinities jsonb,requirements jsonb)
returns boolean language plpgsql immutable security invoker set search_path='' as $$
declare child jsonb;
begin
 if requirements is null or requirements='null'::jsonb then return true; end if;
 if requirements ? 'affinity' then return coalesce(affinities ? (requirements->>'affinity'),false); end if;
 if requirements ? 'allOf' then
  if jsonb_array_length(requirements->'allOf')=0 then return false; end if;
  for child in select value from jsonb_array_elements(requirements->'allOf') loop
   if not public.meets_affinity(affinities,child) then return false; end if;
  end loop; return true;
 end if;
 if requirements ? 'anyOf' then
  for child in select value from jsonb_array_elements(requirements->'anyOf') loop
   if public.meets_affinity(affinities,child) then return true; end if;
  end loop;
 end if;
 return false;
end $$;
revoke all on function public.meets_affinity(jsonb,jsonb) from public,anon;
grant execute on function public.meets_affinity(jsonb,jsonb) to authenticated,service_role;
create temporary table migration_starter_kits(legend_id text primary key,dice text[]) on commit drop;

-- Retain legal migrated slots, then fill from owned legal Cards in collector order.
update public.loadouts l set die_ids=case when exists(select 1 from unnest(l.die_ids) d left join public.content_catalog c on c.id=d where c.id is null or not c.enabled) then (select dice from migration_starter_kits where legend_id=l.legend_id) else l.die_ids end, card_ids=array(
 select candidate.id from (
 select distinct on(c.id) c.id,coalesce(old.ordinality,1000) slot,(c.definition->>'collectorNumber')::int number
 from public.inventory i join public.content_catalog c on c.id=i.content_id
 join public.content_catalog legend on legend.id=l.legend_id
 left join lateral (select o.ordinality from unnest(l.card_ids) with ordinality o(id,ordinality) left join legacy_card_ids m on m.old_id=o.id where coalesce(m.new_id,o.id)=c.id order by o.ordinality limit 1) old on true
 where i.user_id=l.user_id and c.kind='card' and c.enabled and public.meets_affinity(legend.definition->'affinities',c.definition->'affinityRequirements')
 ) candidate order by candidate.slot,candidate.number limit 4
);
create or replace function public.validate_saved_loadout() returns trigger language plpgsql security invoker set search_path='' as $$
declare piece text; affinities jsonb; requirements jsonb;
begin
  if (select count(distinct c) from unnest(new.card_ids) c) <> 4 then raise exception 'Choose four distinct cards'; end if;
  if not exists(select 1 from public.content_catalog where id=new.legend_id and kind='legend' and enabled) then raise exception 'Invalid Legend'; end if;
  select definition->'affinities' into affinities from public.content_catalog where id=new.legend_id;
  foreach piece in array new.card_ids loop
    if not exists(select 1 from public.content_catalog where id=piece and kind='card' and enabled) then raise exception 'Invalid card'; end if;
    select definition->'affinityRequirements' into requirements from public.content_catalog where id=piece;
    if not public.meets_affinity(affinities,requirements) then raise exception 'Card % is incompatible with Legend Affinities',piece; end if;
  end loop;
  foreach piece in array new.die_ids loop
    if not exists(select 1 from public.content_catalog where id=piece and kind='die' and enabled) then raise exception 'Invalid die'; end if;
  end loop;
  foreach piece in array array[new.legend_id] || new.card_ids || new.die_ids loop
    if not exists(select 1 from public.inventory where user_id=new.user_id and content_id=piece) then raise exception 'Content is not owned'; end if;
  end loop;
  new.updated_at=now(); return new;
end $$;

