insert into public.inventory(user_id,content_id,source) select i.user_id,m.new_id,'shared-pool-migration' from public.inventory i join legacy_card_ids m on m.old_id=i.content_id on conflict do nothing;
insert into migration_starter_kits values ('basajaun',array['standard-d12','standard-d8','guardian-d6']),('anansi',array['trickster-d8','standard-d6','standard-d4']),('tengu',array['tengu-d6-0','standard-d8','standard-d6']),('leshy',array['leshy-d8-0','standard-d8','standard-d6']),('quetzalcoatl',array['quetzalcoatl-d10-0','standard-d8','standard-d6']),('maui',array['maui-d10-0','standard-d8','standard-d6']);
insert into public.inventory(user_id,content_id,source) select i.user_id,piece,'omen-catalog-migration' from public.inventory i join migration_starter_kits k on k.legend_id=i.content_id cross join lateral unnest(k.dice) piece on conflict do nothing;
